(window.__qhadithX=window.__qhadithX||{})[81]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1474","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1474","x":"Narrated `Abdullah bin `Umar:\n\nThe Prophet (ﷺ) said, \"A man keeps on asking others for something till he comes on the Day of Resurrection without any piece of flesh on his face.\" The Prophet (ﷺ) added, \"On the Day of Resurrection, the Sun will come near (to, the people) to such an extent that the sweat will reach up to the middle of the ears, so, when all the people are in that state, they will ask Adam for help, and then Moses, and then Muhammad (p.b.u.h).\" The sub-narrator added \"Muhammad will intercede with Allah to judge amongst the people. He will proceed on till he will hold the ring of the door (of Paradise) and then Allah will exalt him to Maqam Mahmud (the privilege of intercession, etc.). And all the people of the gathering will send their praises to Allah.","ar":"حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ، قَالَ سَمِعْتُ حَمْزَةَ بْنَ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ ـ رضى الله عنه ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ مَا يَزَالُ الرَّجُلُ يَسْأَلُ النَّاسَ حَتَّى يَأْتِيَ يَوْمَ الْقِيَامَةِ لَيْسَ فِي وَجْهِهِ مُزْعَةُ لَحْمٍ ‏\"‏‏.‏ وَقَالَ إِنَّ الشَّمْسَ تَدْنُو يَوْمَ الْقِيَامَةِ حَتَّى يَبْلُغَ الْعَرَقُ نِصْفَ الأُذُنِ، فَبَيْنَا هُمْ كَذَلِكَ اسْتَغَاثُوا بِآدَمَ، ثُمَّ بِمُوسَى، ثُمَّ بِمُحَمَّدٍ صلى الله عليه وسلم ‏\"‏‏.‏ وَزَادَ عَبْدُ اللَّهِ حَدَّثَنِي اللَّيْثُ حَدَّثَنِي ابْنُ أَبِي جَعْفَرٍ ‏\"‏ فَيَشْفَعُ لِيُقْضَى بَيْنَ الْخَلْقِ، فَيَمْشِي حَتَّى يَأْخُذَ بِحَلْقَةِ الْبَابِ، فَيَوْمَئِذٍ يَبْعَثُهُ اللَّهُ مَقَامًا مَحْمُودًا، يَحْمَدُهُ أَهْلُ الْجَمْعِ كُلُّهُمْ ‏\"‏‏.‏ وَقَالَ مُعَلًّى حَدَّثَنَا وُهَيْبٌ، عَنِ النُّعْمَانِ بْنِ رَاشِدٍ، عَنْ عَبْدِ اللَّهِ بْنِ مُسْلِمٍ، أَخِي الزُّهْرِيِّ عَنْ حَمْزَةَ، سَمِعَ ابْنَ عُمَرَ ـ رضى الله عنهما ـ عَنِ النَّبِيِّ صلى الله عليه وسلم فِي الْمَسْأَلَةِ‏.‏","v":[]}],"15":[{"c":"Sunan Abu Dawud","r":"Hadith 817","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-817","x":"‘Amr b. Huraith said:\n\nAs if I am hearing the voice of the prophet (may peace by upon him) who would recite at the morning prayer \"Oh, but I call to witness the planets, the stars which rise and set\"(surah 81:15-16)","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ، أَخْبَرَنَا عِيسَى، - يَعْنِي ابْنَ يُونُسَ - عَنْ إِسْمَاعِيلَ، عَنْ أَصْبَغَ، مَوْلَى عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ كَأَنِّي أَسْمَعُ صَوْتَ النَّبِيِّ صلى الله عليه وسلم يَقْرَأُ فِي صَلاَةِ الْغَدَاةِ ‏{‏ فَلاَ أُقْسِمُ بِالْخُنَّسِ * الْجَوَارِ الْكُنَّسِ ‏}‏ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 817","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-817","x":"It was narrated that ‘Amr bin Huraith said:\n\n\"I performed prayer with the Prophet (ﷺ) when he was reciting in the Fajr, and it is as if I can hear him reciting: ‘So verily, I swear by the planets that recede. And by the planets that move swiftly and hide themselves.’\"[81:15-16]","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، عَنْ أَصْبَغَ، مَوْلَى عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ صَلَّيْنَا مَعَ النَّبِيِّ ـ صلى الله عليه وسلم ـ فَكَانَ يَقْرَأُ فِي الْفَجْرِ فَكَأَنِّي أَسْمَعُ قِرَاءَتَهُ ‏{فَلاَ أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 475","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-475","x":"'Amr b. Huraith reported:\n\nI said the dawn prayer behind the Apostle of (ﷺ) and heard him reciting: 'Nay. I call to witness the stars, running their courses and setting\" (al-Qur'an, lxxxi. 15-16) and Done of us bent his back till he completed prostration.","ar":"حَدَّثَنَا مُحْرِزُ بْنُ عَوْنِ بْنِ أَبِي عَوْنٍ، حَدَّثَنَا خَلَفُ بْنُ خَلِيفَةَ الأَشْجَعِيُّ أَبُو أَحْمَدَ، عَنِ الْوَلِيدِ بْنِ سَرِيعٍ، مَوْلَى آلِ عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ صَلَّيْتُ خَلْفَ النَّبِيِّ صلى الله عليه وسلم الْفَجْرَ فَسَمِعْتُهُ يَقْرَأُ ‏{‏ فَلاَ أُقْسِمُ بِالْخُنَّسِ * الْجَوَارِ الْكُنَّسِ‏}‏ وَكَانَ لاَ يَحْنِي رَجُلٌ مِنَّا ظَهْرَهُ حَتَّى يَسْتَتِمَّ سَاجِدًا ‏.‏","v":[]}],"16":[{"c":"Sunan Abu Dawud","r":"Hadith 817","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-817","x":"‘Amr b. Huraith said:\n\nAs if I am hearing the voice of the prophet (may peace by upon him) who would recite at the morning prayer \"Oh, but I call to witness the planets, the stars which rise and set\"(surah 81:15-16)","ar":"حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ، أَخْبَرَنَا عِيسَى، - يَعْنِي ابْنَ يُونُسَ - عَنْ إِسْمَاعِيلَ، عَنْ أَصْبَغَ، مَوْلَى عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ كَأَنِّي أَسْمَعُ صَوْتَ النَّبِيِّ صلى الله عليه وسلم يَقْرَأُ فِي صَلاَةِ الْغَدَاةِ ‏{‏ فَلاَ أُقْسِمُ بِالْخُنَّسِ * الْجَوَارِ الْكُنَّسِ ‏}‏ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 5, Hadith 817","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-5/Hadith-817","x":"It was narrated that ‘Amr bin Huraith said:\n\n\"I performed prayer with the Prophet (ﷺ) when he was reciting in the Fajr, and it is as if I can hear him reciting: ‘So verily, I swear by the planets that recede. And by the planets that move swiftly and hide themselves.’\"[81:15-16]","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، عَنْ أَصْبَغَ، مَوْلَى عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ صَلَّيْنَا مَعَ النَّبِيِّ ـ صلى الله عليه وسلم ـ فَكَانَ يَقْرَأُ فِي الْفَجْرِ فَكَأَنِّي أَسْمَعُ قِرَاءَتَهُ ‏{فَلاَ أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 475","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-475","x":"'Amr b. Huraith reported:\n\nI said the dawn prayer behind the Apostle of (ﷺ) and heard him reciting: 'Nay. I call to witness the stars, running their courses and setting\" (al-Qur'an, lxxxi. 15-16) and Done of us bent his back till he completed prostration.","ar":"حَدَّثَنَا مُحْرِزُ بْنُ عَوْنِ بْنِ أَبِي عَوْنٍ، حَدَّثَنَا خَلَفُ بْنُ خَلِيفَةَ الأَشْجَعِيُّ أَبُو أَحْمَدَ، عَنِ الْوَلِيدِ بْنِ سَرِيعٍ، مَوْلَى آلِ عَمْرِو بْنِ حُرَيْثٍ عَنْ عَمْرِو بْنِ حُرَيْثٍ، قَالَ صَلَّيْتُ خَلْفَ النَّبِيِّ صلى الله عليه وسلم الْفَجْرَ فَسَمِعْتُهُ يَقْرَأُ ‏{‏ فَلاَ أُقْسِمُ بِالْخُنَّسِ * الْجَوَارِ الْكُنَّسِ‏}‏ وَكَانَ لاَ يَحْنِي رَجُلٌ مِنَّا ظَهْرَهُ حَتَّى يَسْتَتِمَّ سَاجِدًا ‏.‏","v":[]}],"23":[{"c":"Sahih Muslim","r":"Hadith 177a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-177a","x":"It is narrated on the authority of Masruq that he said:\n\nI was resting at (the house of) 'A'isha that she said: O Abu 'A'isha (kunya of Masruq), there are three things, and he who affirmed even one of them fabricated the greatest lie against Allah. I asked that they were. She said: He who presumed that Muhammad (ﷺ) saw his Lord (with his ocular vision) fabricated the greatest lie against Allah. I was reclining but then sat up and said: Mother of the Faithful, wait a bit and do not be in a haste. Has not Allah (Mighty and Majestic) said:\" And truly he saw him on the clear horizon\" (Al-Qur'an, Surat at-Takwir, 81:23) and\" he saw Him in another descent\" (Al-Qur'an, Surat Najm 53:13)? She said: I am the first of this Ummah who asked the Messenger of Allah (ﷺ) about it, and he said: Verily he is Gabriel. I have never seen him in his original form in which he was created except on those two occasions (to which these verses refer); I saw him descending from the heaven and filling (the space) from the sky to the earth with the greatness of his bodily structure. She said: Have you not heard Allah saying: \"Eyes comprehend Him not, but He comprehends (all) vision. and He is Subtle, and All-Aware\" (Al-Qur'an, Surat al-An`am 6:103)? (She, i.e. 'A'isha, further said): Have you not heard that, verily, Allah says: \"And it is not for any human being that Allah should speak to him except by revelation or from behind a partition or that He sends a messenger to reveal, by His permission, what He wills. Indeed, He is Most High and Wise.\" (Al-Qur'an, Surat ash-Shura, 42:51) She said: He who presumes that the Messenger of Allah (ﷺ) concealed anything from the Book of Allah fabricates the greatest lie against Allah. Allah says: \"O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allah will protect you from the people. Indeed, Allah does not guide the disbelieving people.\" (Al-Qur'an, Surat al-Ma'idah, 5:67). She said: He who presumes that he would inform about what was going to happen tomorrow fabricates the greatest lie against Allah. And Allah says \"Say, 'None in the heavens and earth knows the unseen except Allah, and they do not perceive when they will be resurrected.'\" (Al-Qur'an, Surat an-Naml, 27:65).","ar":"حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ، عَنْ دَاوُدَ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، قَالَ كُنْتُ مُتَّكِئًا عِنْدَ عَائِشَةَ فَقَالَتْ يَا أَبَا عَائِشَةَ ثَلاَثٌ مَنْ تَكَلَّمَ بِوَاحِدَةٍ مِنْهُنَّ فَقَدْ أَعْظَمَ عَلَى اللَّهِ الْفِرْيَةَ ‏.‏ قُلْتُ مَا هُنَّ قَالَتْ مَنْ زَعَمَ أَنَّ مُحَمَّدًا صلى الله عليه وسلم رَأَى رَبَّهُ فَقَدْ أَعْظَمَ عَلَى اللَّهِ الْفِرْيَةَ ‏.‏ قَالَ وَكُنْتُ مُتَّكِئًا فَجَلَسْتُ فَقُلْتُ يَا أُمَّ الْمُؤْمِنِينَ أَنْظِرِينِي وَلاَ تَعْجَلِينِي أَلَمْ يَقُلِ اللَّهُ عَزَّ وَجَلَّ ‏{‏ وَلَقَدْ رَآهُ بِالأُفُقِ الْمُبِينِ‏}‏ ‏{‏ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى‏}‏ ‏.‏ فَقَالَتْ أَنَا أَوَّلُ هَذِهِ الأُمَّةِ سَأَلَ عَنْ ذَلِكَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ إِنَّمَا هُوَ جِبْرِيلُ لَمْ أَرَهُ عَلَى صُورَتِهِ الَّتِي خُلِقَ عَلَيْهَا غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ رَأَيْتُهُ مُنْهَبِطًا مِنَ السَّمَاءِ سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ إِلَى الأَرْضِ ‏\"‏ ‏.‏ فَقَالَتْ أَوَلَمْ تَسْمَعْ أَنَّ اللَّهَ يَقُولُ ‏{‏ لاَ تُدْرِكُهُ الأَبْصَارُ وَهُوَ يُدْرِكُ الأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ‏}‏ أَوَلَمْ تَسْمَعْ أَنَّ اللَّهَ يَقُولُ ‏{‏ وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ إِلاَّ وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولاً فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ‏}‏ قَالَتْ وَمَنْ زَعَمَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَتَمَ شَيْئًا مِنْ كِتَابِ اللَّهِ فَقَدْ أَعْظَمَ عَلَى اللَّهِ الْفِرْيَةَ وَاللَّهُ يَقُولُ ‏{‏ يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ‏}‏ ‏.‏ قَالَتْ وَمَنْ زَعَمَ أَنَّهُ يُخْبِرُ بِمَا يَكُونُ فِي غَدٍ فَقَدْ أَعْظَمَ عَلَى اللَّهِ الْفِرْيَةَ وَاللَّهُ يَقُولُ ‏{‏ قُلْ لاَ يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلاَّ اللَّهُ‏}‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3068","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3068","x":"Narrated Masruq:\n\n\"I was reclining in the presence of 'Aishah when she said: 'O Abu 'Aishah! There are three things, whoever speaks of one of them, then he has uttered one of the worst lies against Allah. Whoever claims that Muhammad saw his Lord. Then he has uttered one the worst lies against Allah, Allah says: No vision can grasp Him, but His grasp is over all vision, and He is the Most Subtle, Well-Acquainted with all things (6:103). It is not for any human being that Allah should speak to him unless (it be) by revelation or from behind a veil (42:51).' I was reclining so I sat up an said: 'O Mother of the Believers! Take your time with me and do not be hasty with me! Did Allah Most High not say: And indeed he saw him at a second descent (53:13). (And) 'And indeed he saw him in the clear horizon (81:23).' She said 'By Allah! I was the first who asked the Messenger of Allah (ﷺ) about this. He said: \"That was only Jibril. I did not see him in the appearance he was created in except for these two times. I saw him descending from the heavens, and due to his tremendous size he filled what was between the heavens and the earth.\" \"And whoever claimed that Muhammad hid anything that Allah revealed to him, then he uttered one of the worst lies against Allah. Allah says: O Messenger! Proclaim what has been sent down to you from your Lord (5:67).\" \"And whoever claimed that he (ﷺ) knew what would be tomorrow, then he has uttered one of the worst lies against Allah. Allah says: Say: 'None in the heavens and in the earth knows the unseen but Allah (27:65).'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا إِسْحَاقُ بْنُ يُوسُفَ الأَزْرَقُ، حَدَّثَنَا دَاوُدُ بْنُ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ مَسْرُوقٍ، قَالَ كُنْتُ مُتَّكِئًا عِنْدَ عَائِشَةَ فَقَالَتْ يَا أَبَا عَائِشَةَ ثَلاَثٌ مَنْ تَكَلَّمَ بِوَاحِدَةٍ مِنْهُنَّ فَقَدْ أَعْظَمَ عَلَى اللَّهِ الْفِرْيَةَ مَنْ زَعَمَ أَنَّ مُحَمَّدًا رَأَى رَبَّهُ فَقَدْ أَعْظَمَ الْفِرْيَةَ عَلَى اللَّهِ وَاللَّهُ يَقُولُ ‏:‏ ‏(‏ لَا تُدْرِكُهُ الأَبْصَارُ وَهُوَ يُدْرِكُ الأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ ‏)‏ ، ‏(‏ مَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ إِلاَّ وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ ‏)‏ وَكُنْتُ مُتَّكِئًا فَجَلَسْتُ فَقُلْتُ يَا أُمَّ الْمُؤْمِنِينَ أَنْظِرِينِي وَلاَ تُعْجِلِينِي أَلَيْسَ يَقُولُ اللَّهُ ‏:‏ ‏(‏ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ‏)‏، ‏(‏ وَلََقَدْ رَآهُ بِالأُفُقِ الْمُبِينِ ‏)‏ قَالَتْ أَنَا وَاللَّهِ أَوَّلُ مَنْ سَأَلَ عَنْ هَذَا رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ إِنَّمَا ذَاكَ جِبْرِيلُ مَا رَأَيْتُهُ فِي الصُّورَةِ الَّتِي خُلِقَ فِيهَا غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ رَأَيْتُهُ مُنْهَبِطًا مِنَ السَّمَاءِ سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ ‏\"‏ ‏.‏ وَمَنْ زَعَمَ أَنَّ مُحَمَّدًا كَتَمَ شَيْئًا مِمَّا أَنْزَلَ اللَّهُ عَلَيْهِ فَقَدْ أَعْظَمَ الْفِرْيَةَ عَلَى اللَّهِ يَقُولُ اللَّهُ ‏:‏ ‏(‏ يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ ‏)‏ وَمَنْ زَعَمَ أَنَّهُ يَعْلَمُ مَا فِي غَدٍ فَقَدْ أَعْظَمَ الْفِرْيَةَ عَلَى اللَّهِ وَاللَّهُ يَقُولُ ‏:‏ ‏(‏قُلْ لاَ يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلاَّ اللَّهُ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَمَسْرُوقُ بْنُ الأَجْدَعِ يُكْنَى أَبَا عَائِشَةَ وَهُوَ مَسْرُوقُ بْنُ عَبْدِ الرَّحْمَنِ وَهَكَذَا كَانَ اسْمُهُ فِي الدِّيوَانِ ‏.‏","v":[]}]};